// Read-only inspector for circuits generated by the checked-out Rust compiler.
// The Python driver builds this file in a temporary Cargo package.
use sha2::{Digest, Sha256};

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|byte| format!("{byte:02x}")).collect()
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let profile = mdoc_zk_compile::LigeroProfile {
        rateinv: args[1].parse().unwrap(),
        nreq: args[2].parse().unwrap(),
    };
    let p256 = compile_algebra::p256::P256Field::new();
    let (sig, config) = mdoc_zk_compile::generate_sig_circuit(&p256, profile).unwrap();
    let (nw, nq) = runtime_proto::witness_and_constraint_count(&sig);
    println!("PARAM sig {} {} {} {}", config.block_enc, nw, nq, hex(&sig.id));
    let gf128 = compile_algebra::gf2_128::Gf2_128Field::new();
    for attributes in 1..=4 {
        let (hash, config) =
            mdoc_zk_compile::generate_hash_circuit(&gf128, attributes, profile).unwrap();
        let (nw, nq) = runtime_proto::witness_and_constraint_count(&hash);
        let mut combined = Sha256::new();
        combined.update(sig.id);
        combined.update(hash.id);
        println!("PARAM hash {} {} {} {} {} {}", attributes, config.block_enc,
                 nw, nq, hex(&hash.id), hex(&combined.finalize()));
    }
}
